@props(['documents' => collect(), 'type' => 'Invoice', 'createUrl' => null])

<div class="font-outfit" x-data="{ rows: @js($documents), filters: { search: '', date: '' }, get filteredRows() { const search = this.filters.search.toLowerCase(); return this.rows.filter(row => { const haystack = `${row.document_no || ''} ${row.po_no || ''} ${row.company_name || ''}`.toLowerCase(); return (!search || haystack.includes(search)) && (!this.filters.date || row.document_date === this.filters.date); }); }, resetFilters() { this.filters = { search: '', date: '' }; }, formatDate(value) { return value ? String(value).split('-').reverse().join('/') : '—'; } }">
