            <input x-model="filters.search" type="search" :placeholder="`Cari nombor ${@js($type)}, PO atau pembekal`" :aria-label="`Cari ${@js($type)}`" class="h-11 min-w-40 flex-1 rounded-lg border-0 bg-white px-3 text-theme-sm text-gray-700 shadow-theme-xs focus:ring-2 focus:ring-brand-500/20 dark:bg-gray-800 dark:text-gray-300">
            <input x-model="filters.date" type="date" aria-label="Tarikh" class="h-11 w-44 shrink-0 rounded-lg border-0 bg-white px-3 text-theme-sm text-gray-700 shadow-theme-xs focus:ring-2 focus:ring-brand-500/20 dark:bg-gray-800 dark:text-gray-300">
            <button type="button" @click="resetFilters()" class="inline-flex h-11 shrink-0 items-center justify-center rounded-lg border border-gray-300 bg-white px-4 text-theme-sm font-medium text-gray-700 shadow-theme-xs hover:bg-gray-50 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-400 dark:hover:bg-white/[0.03]">{{ __('See all') }}</button>
            @if ($createUrl)
                <a href="{{ $createUrl }}" class="inline-flex h-11 shrink-0 items-center justify-center rounded-lg bg-brand-500 px-4 text-theme-sm font-medium text-white transition hover:bg-brand-600">{{ __('+ Tambah') }} {{ $type }}</a>
            @endif
        </div></div>
        <div class="max-w-full overflow-x-auto"><table class="w-full text-theme-sm leading-6 text-gray-700 dark:text-gray-300">
            <thead class="border-y border-gray-100 bg-gray-50 dark:border-white/[0.05] dark:bg-gray-900"><tr><th class="px-4 py-3 text-start font-semibold text-gray-500 sm:px-6">{{ __('No.') }} {{ $type }}</th><th class="px-4 py-3 text-start font-semibold text-gray-500 sm:px-6">{{ __('No. Purchase Order') }}</th><th class="px-4 py-3 text-start font-semibold text-gray-500 sm:px-6">{{ __('Pembekal') }}</th><th class="px-4 py-3 text-start font-semibold text-gray-500 sm:px-6">{{ __('Tarikh') }}</th><th class="px-4 py-3 text-end font-semibold text-gray-500 sm:px-6">{{ __('Jumlah (RM)') }}</th><th class="px-4 py-3 text-center font-semibold text-gray-500 sm:px-6">{{ __('Tindakan') }}</th></tr></thead>
            <tbody><template x-for="row in filteredRows" :key="row.id"><tr class="border-b border-gray-100 hover:bg-gray-50 dark:border-white/[0.05] dark:hover:bg-white/[0.03]"><td class="px-4 py-3.5 font-medium sm:px-6" x-text="row.document_no"></td><td class="px-4 py-3.5 sm:px-6" x-text="row.po_no || '—'"></td><td class="px-4 py-3.5 font-medium text-gray-800 sm:px-6 dark:text-white/90" x-text="row.company_name || '—'"></td><td class="px-4 py-3.5 sm:px-6" x-text="formatDate(row.document_date)"></td><td class="px-4 py-3.5 text-end tabular-nums sm:px-6" x-text="Number(row.amount || 0).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 })"></td><td class="px-4 py-3.5 text-center sm:px-6"><span class="text-xs text-gray-400 dark:text-gray-500">—</span></td></tr></template><template x-if="filteredRows.length === 0"><tr><td colspan="6" class="px-6 py-12 text-center text-gray-500 dark:text-gray-400">{{ __('Tiada rekod') }} {{ $type }} {{ __('direkodkan.') }}</td></tr></template></tbody>
        </table></div>
    </div>
